CREATE FUNCTION population_top3000_202608_202609_v1.ctx06_release_shape_v3(p_content jsonb,p_selected jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='pg_catalog' SET "TimeZone"='UTC' AS $f$
DECLARE n integer;
BEGIN
IF jsonb_typeof(p_content) IS DISTINCT FROM 'object' OR jsonb_typeof(p_selected) IS DISTINCT FROM 'array' OR jsonb_typeof(p_content->'company_coverage') IS DISTINCT FROM 'array' OR jsonb_typeof(p_content->'instruments') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'CTX06_V3_TYPED_ARRAYS_REQUIRED';END IF;
IF jsonb_array_length(p_selected)<>3000 OR (SELECT count(DISTINCT c->>'company_id') FROM jsonb_array_elements(p_selected)c)<>3000 OR jsonb_array_length(p_content->'company_coverage')<>3000 OR (SELECT count(DISTINCT c->>'company_id') FROM jsonb_array_elements(p_content->'company_coverage')c)<>3000 THEN RAISE EXCEPTION 'CTX06_V3_EXACT_3000_COVERAGE_REQUIRED';END IF;
n:=jsonb_array_length(p_content->'instruments');
IF n>50000 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_content->'instruments')i GROUP BY i->>'company_id' HAVING count(*)>1000) THEN RAISE EXCEPTION 'CTX06_V3_FINITE_INSTRUMENT_BOUND';END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_content->'company_coverage')c WHERE coalesce(c->>'status','') NOT IN('QUALIFIED_INTERVALS','VERIFIED_NO_ELIGIBLE_LISTING') OR jsonb_typeof(c->'source_refs') IS DISTINCT FROM 'array' OR jsonb_array_length(c->'source_refs')=0 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_selected)s WHERE s->>'company_id'=c->>'company_id')) THEN RAISE EXCEPTION 'CTX06_V3_INVALID_COVERAGE';END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_content->'instruments')i WHERE nullif(i->>'security_id','') IS NULL OR nullif(i->>'listing_episode_id','') IS NULL OR nullif(i->>'ticker','') IS NULL OR i->>'listing_start' IS NULL OR NOT isfinite((i->>'listing_start')::timestamptz) OR (i->>'listing_end' IS NOT NULL AND NOT isfinite((i->>'listing_end')::timestamptz)) OR jsonb_typeof(i->'eligible_common_equity') IS DISTINCT FROM 'boolean' OR coalesce(i->>'security_type','') NOT IN('CS','ADRC') OR jsonb_typeof(i#>'{links_evidence,source_refs}') IS DISTINCT FROM 'array' OR jsonb_array_length(i#>'{links_evidence,source_refs}')=0 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_selected)s WHERE s->>'company_id'=i->>'company_id') OR (i->>'listing_end' IS NOT NULL AND (i->>'listing_end')::timestamptz<=(i->>'listing_start')::timestamptz)) THEN RAISE EXCEPTION 'CTX06_V3_INVALID_INSTRUMENT';END IF;
IF (SELECT count(DISTINCT (i->>'company_id',i->>'security_id',i->>'listing_episode_id')) FROM jsonb_array_elements(p_content->'instruments')i)<>n THEN RAISE EXCEPTION 'CTX06_V3_DUPLICATE_IDENTITY';END IF;
RETURN jsonb_build_object('structural_checks_passed',true,'company_count',3000,'instrument_count',n,'evidence_qualified',false,'family_accepted',false);
END $f$;

CREATE FUNCTION population_top3000_202608_202609_v1.ctx06_release_ingest_v3(p_claim bigint,p_content jsonb,p_versions jsonb,p_review bigint)
RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' SET "TimeZone"='UTC' AS $f$
DECLARE ctl jsonb;cl jsonb;ass jsonb;e jsonb;s jsonb;shape jsonb;dep jsonb;r record;rh text;daily uuid;existing boolean;ev bigint;relation_before bigint;
BEGIN
ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
SELECT details INTO cl FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=p_claim AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5';
SELECT details INTO ass FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=(cl->>'assignment_event_id')::bigint AND event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5';
IF cl IS NULL OR ass IS NULL OR cl->>'executor' IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' OR cl->>'owner_id' IS DISTINCT FROM ctl->>'owner_id' OR cl->>'owner_fence' IS DISTINCT FROM '3' OR cl->>'stop_generation' IS DISTINCT FROM '1' OR cl->>'scope_sha256' IS DISTINCT FROM ctl->>'scope_sha256' OR cl->>'exclusive_component' IS DISTINCT FROM 'CTX06_PRACTICAL_BREADTH_PRODUCER_V2' OR cl->>'expires_at' IS NULL OR (cl->>'expires_at')::timestamptz<=clock_timestamp() OR ass->>'assigned_executor' IS DISTINCT FROM cl->>'executor' OR ass->>'root_will_not_concurrently_modify' IS DISTINCT FROM 'true' OR encode(sha256(convert_to(ass::text,'UTF8')),'hex') IS DISTINCT FROM cl->>'assignment_details_sha256' OR ass->>'not_after' IS NULL OR (ass->>'not_after')::timestamptz<=clock_timestamp() OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event IN('ENGINEERING_ASSIGNMENT_COMPLETED_V5','ENGINEERING_ASSIGNMENT_EFFECTS_RECONCILED_RELEASE_V5') AND details->>'claim_event_id'=p_claim::text) THEN RAISE EXCEPTION 'CTX06_V3_EXACT_CURRENT_UNRELEASED_CLAIM_REQUIRED';END IF;
IF pg_column_size(p_content)>16777216 OR p_content->>'fixture_only' IS DISTINCT FROM 'false' OR p_content->>'full_period_verified' IS DISTINCT FROM 'true' OR p_content->>'window_start' IS DISTINCT FROM '2026-08-01' OR p_content->>'window_end' IS DISTINCT FROM '2026-09-30' OR p_content->>'evidence_semantics' IS DISTINCT FROM 'QUALIFIED_DATED_INSTRUMENT_INTERVALS_WITH_EXPLICIT_LIFECYCLE_COVERAGE_V2' THEN RAISE EXCEPTION 'CTX06_V3_REAL_FINITE_FULL_PERIOD_RELEASE_REQUIRED';END IF;
relation_before:=pg_total_relation_size('population_top3000_202608_202609_v1.ctx06_practical_release_v2'::regclass);
rh:=encode(sha256(convert_to(p_content::text,'UTF8')),'hex');
daily:=(ass#>>'{input_versions,daily_run_id}')::uuid;
IF p_versions->>'instrument_manifest_sha256' IS DISTINCT FROM rh OR p_versions->>'ctx06_bundle_sha256' IS DISTINCT FROM population_top3000_202608_202609_v1.ctx06_practical_bundle_sha_v2() THEN RAISE EXCEPTION 'CTX06_V3_RELEASE_OR_CODE_HASH_CHANGED';END IF;
SELECT details INTO e FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=p_review AND event='CTX06_DATED_RELEASE_INDEPENDENT_REVIEW_V2';
IF e IS NULL OR e->>'approved' IS DISTINCT FROM 'true' OR e->>'fixture_only' IS DISTINCT FROM 'false' OR e->>'full_period_instrument_evidence_verified' IS DISTINCT FROM 'true' OR e->>'instrument_manifest_sha256' IS DISTINCT FROM rh OR e->>'ctx06_bundle_sha256' IS DISTINCT FROM p_versions->>'ctx06_bundle_sha256' OR e->>'owner_id' IS DISTINCT FROM ctl->>'owner_id' OR e->>'owner_fence' IS DISTINCT FROM '3' OR e->>'stop_generation' IS DISTINCT FROM '1' OR e->>'scope_sha256' IS DISTINCT FROM ctl->>'scope_sha256' OR nullif(e->>'producer','') IS NULL OR nullif(e->>'reviewer','') IS NULL OR e->>'producer' IS NOT DISTINCT FROM e->>'reviewer' THEN RAISE EXCEPTION 'CTX06_V3_ACTUAL_INDEPENDENT_SOURCE_REVIEW_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task t JOIN population_top3000_202608_202609_v1.pipeline_commit c USING(task_id) WHERE t.task_id=(e->>'source_prerequisite_task_id')::uuid AND t.family_id='REF01' AND t.status='COMPLETE' AND c.new_committed_units>0 AND c.output_sha256=e->>'source_prerequisite_output_sha256' AND t.input_versions->>'cohort_sha256'=p_versions->>'cohort_sha256' AND t.input_versions->>'policy_sha256'=p_versions->>'policy_sha256' AND t.input_versions->>'membership_acceptance_sha256'=p_versions->>'membership_acceptance_sha256') THEN RAISE EXCEPTION 'CTX06_V3_REAL_COMPLETE_SOURCE_PREREQUISITE_REQUIRED';END IF;
SELECT content->'companies' INTO s FROM population_top3000_202608_202609_v1.ref01_practical_snapshot_v1 WHERE snapshot_sha256=p_versions->>'cohort_sha256';
shape:=population_top3000_202608_202609_v1.ctx06_release_shape_v3(p_content,s);
existing:=EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ctx06_practical_release_v2 WHERE release_sha256=rh);
INSERT INTO population_top3000_202608_202609_v1.ctx06_practical_release_v2(release_sha256,cohort_sha256,acceptance_sha256,policy_sha256,daily_run_id,daily_input_versions_sha256,independent_review_event_id,content) VALUES(rh,p_versions->>'cohort_sha256',p_versions->>'membership_acceptance_sha256',p_versions->>'policy_sha256',daily,p_versions->>'daily_input_versions_sha256',p_review,p_content) ON CONFLICT(release_sha256) DO NOTHING;
SELECT * INTO STRICT r FROM population_top3000_202608_202609_v1.ctx06_practical_release_v2 WHERE release_sha256=rh;
IF r.content IS DISTINCT FROM p_content OR r.independent_review_event_id IS DISTINCT FROM p_review THEN RAISE EXCEPTION 'CTX06_V3_IMMUTABLE_RELEASE_CONFLICT';END IF;
IF pg_total_relation_size('population_top3000_202608_202609_v1.ctx06_practical_release_v2'::regclass)-relation_before>33554432 THEN RAISE EXCEPTION 'CTX06_V3_RELATION_GROWTH_BOUND';END IF;
dep:=population_top3000_202608_202609_v1.ctx06_practical_dependencies_v2(daily,p_versions);
IF dep->>'ready' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'CTX06_V3_FULL_SOURCE_BINDING_NOT_QUALIFIED';END IF;
IF NOT existing THEN INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX06_PRACTICAL_RELEASE_BOUND_V3',ctl||jsonb_build_object('assignment_event_id',cl->>'assignment_event_id','claim_event_id',p_claim,'instrument_manifest_sha256',rh,'independent_review_event_id',p_review,'source_prerequisite_task_id',e->>'source_prerequisite_task_id','shape',shape,'production_wake_performed',false,'first_batch_qualified',false,'family_accepted',false)) RETURNING event_id INTO ev;END IF;
RETURN jsonb_build_object('release_sha256',rh,'bound',true,'idempotent_replay',existing,'event_id',ev,'production_wake_performed',false,'family_accepted',false);
END $f$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.ctx06_release_shape_v3(jsonb,jsonb),population_top3000_202608_202609_v1.ctx06_release_ingest_v3(bigint,jsonb,jsonb,bigint) FROM PUBLIC,anon,authenticated;
